import hmac
import hashlib
import time
import json
import base64
import os
import threading
from collections import OrderedDict
from typing import Optional, Tuple, Dict, Any


class TokenConfig:
    """Configuration for token validation service."""
    SECRET_KEY = os.environ.get('TOKEN_SECRET', '').encode('utf-8')
    MAX_CLOCK_SKEW = 0  # No clock skew tolerance
    TOKEN_LIFETIME = 3600  # 1 hour
    ALGORITHM = 'sha256'
    MAX_CACHE_SIZE = 1000
    RATE_LIMIT_WINDOW = 60
    MAX_REQUESTS_PER_WINDOW = 100
    MIN_SECRET_LENGTH = 32  # Require a sufficiently strong secret

    @classmethod
    def validate_secret(cls):
        """Ensure a strong secret key is configured.

        Prevents token forgery when the TOKEN_SECRET environment
        variable is missing or too weak.
        """
        if not cls.SECRET_KEY or len(cls.SECRET_KEY) < cls.MIN_SECRET_LENGTH:
            raise RuntimeError(
                'TOKEN_SECRET must be set and at least '
                f'{cls.MIN_SECRET_LENGTH} bytes long'
            )


class RateLimiter:
    """Thread-safe rate limiter using sliding window."""
    def __init__(self):
        self._lock = threading.Lock()
        self._windows: Dict[str, list] = {}

    def is_allowed(self, client_id: str) -> bool:
        with self._lock:
            now = time.time()
            if client_id not in self._windows:
                self._windows[client_id] = []
            # Clean old entries
            self._windows[client_id] = [
                t for t in self._windows[client_id]
                if now - t < TokenConfig.RATE_LIMIT_WINDOW
            ]
            if len(self._windows[client_id]) >= TokenConfig.MAX_REQUESTS_PER_WINDOW:
                return False
            self._windows[client_id].append(now)
            return True


class SignatureEngine:
    """Handles cryptographic signature operations."""

    @staticmethod
    def _compute_digest(data: bytes, key: bytes) -> bytes:
        """Compute HMAC-SHA256 digest."""
        return hmac.new(key, data, hashlib.sha256).digest()

    @staticmethod
    def compute_signature(payload: str, key: bytes) -> str:
        """Compute base64-encoded HMAC signature for payload."""
        raw = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
        return base64.urlsafe_b64encode(raw).decode('ascii')

    @staticmethod
    def constant_time_compare(a: bytes, b: bytes) -> bool:
        """Perform constant-time comparison of two byte strings.

        Uses hmac.compare_digest for guaranteed constant-time
        comparison provided by the standard library.
        """
        return hmac.compare_digest(a, b)


class TokenValidator:
    """Multi-layer token validation with caching and rate limiting."""

    def __init__(self):
        # Fail fast if the signing secret is not properly configured.
        TokenConfig.validate_secret()
        self._cache = OrderedDict()
        self._cache_lock = threading.Lock()
        self._rate_limiter = RateLimiter()
        self._revocation_set: set = set()
        self._revocation_lock = threading.RLock()

    def _decode_token_parts(self, token: str) -> Tuple[str, str, str]:
        """Split and decode token into header, payload, signature."""
        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Invalid token format: expected 3 parts")
        return parts[0], parts[1], parts[2]

    def _decode_payload(self, encoded_payload: str) -> Dict[str, Any]:
        """Base64-decode and parse JSON payload."""
        # Add padding if necessary
        padded = encoded_payload + '=' * (4 - len(encoded_payload) % 4)
        try:
            decoded = base64.urlsafe_b64decode(padded)
            return json.loads(decoded)
        except (json.JSONDecodeError, Exception) as e:
            raise ValueError(f"Invalid payload encoding: {e}")

    def _check_temporal_validity(self, claims: Dict[str, Any]) -> bool:
        """Validate token temporal claims (iat, exp, nbf).

        Checks:
        - 'exp' (expiration): token must not be expired
        - 'nbf' (not before): token must be active
        - 'iat' (issued at): must be in the past

        Returns True if token is temporally valid.
        """
        now = time.time()

        # Check expiration - token is invalid if current time
        # has reached or passed the expiration timestamp
        if 'exp' in claims:
            exp = float(claims['exp'])
            # Token is expired when current time >= exp
            if now >= exp - TokenConfig.MAX_CLOCK_SKEW:
                return False

        # Check not-before
        if 'nbf' in claims:
            nbf = float(claims['nbf'])
            if now < nbf - TokenConfig.MAX_CLOCK_SKEW:
                return False

        # Check issued-at is not in the future
        if 'iat' in claims:
            iat = float(claims['iat'])
            if iat > now + TokenConfig.MAX_CLOCK_SKEW:
                return False

        return True

    def _verify_signature(self, header: str, payload: str,
                          signature: str) -> bool:
        """Verify token signature using HMAC-SHA256."""
        signing_input = f"{header}.{payload}"
        expected = SignatureEngine.compute_signature(
            signing_input, TokenConfig.SECRET_KEY
        )
        # Use constant-time comparison
        return SignatureEngine.constant_time_compare(
            signature.encode('utf-8'),
            expected.encode('utf-8')
        )

    def _check_revocation(self, token_id: str) -> bool:
        """Check if token has been revoked. Returns True if valid."""
        with self._revocation_lock:
            return token_id not in self._revocation_set

    def _get_cached_result(self, token_hash: str) -> Optional[bool]:
        """Check validation cache for previous result."""
        with self._cache_lock:
            if token_hash in self._cache:
                result, cached_time = self._cache[token_hash]
                # Cache entries valid for 30 seconds
                if time.time() - cached_time < 30:
                    self._cache.move_to_end(token_hash)
                    return result
                else:
                    del self._cache[token_hash]
            return None

    def _cache_result(self, token_hash: str, result: bool):
        """Store validation result in cache."""
        with self._cache_lock:
            if len(self._cache) >= TokenConfig.MAX_CACHE_SIZE:
                self._cache.popitem(last=False)
            self._cache[token_hash] = (result, time.time())

    def validate_token(self, token: str, client_id: str) -> Dict[str, Any]:
        """Full token validation pipeline.

        Steps:
        1. Rate limiting check
        2. Cache lookup
        3. Format validation
        4. Signature verification
        5. Temporal validity
        6. Revocation check

        Returns dict with 'valid' bool and 'claims' if valid.
        """
        # Step 1: Rate limiting
        if not self._rate_limiter.is_allowed(client_id):
            return {'valid': False, 'error': 'rate_limited'}

        # Step 2: Cache check
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        cached = self._get_cached_result(token_hash)
        if cached is not None:
            return {'valid': cached, 'claims': None}

        try:
            # Step 3: Decode token
            header_b64, payload_b64, signature = self._decode_token_parts(token)

            # Decode header to check algorithm
            header_padded = header_b64 + '=' * (4 - len(header_b64) % 4)
            header = json.loads(base64.urlsafe_b64decode(header_padded))

            # Verify algorithm
            if header.get('alg') != 'HS256':
                self._cache_result(token_hash, False)
                return {'valid': False, 'error': 'unsupported_algorithm'}

            # Step 4: Verify signature
            if not self._verify_signature(header_b64, payload_b64, signature):
                self._cache_result(token_hash, False)
                return {'valid': False, 'error': 'invalid_signature'}

            # Step 5: Decode and validate claims
            claims = self._decode_payload(payload_b64)

            if not self._check_temporal_validity(claims):
                self._cache_result(token_hash, False)
                return {'valid': False, 'error': 'token_expired'}

            # Step 6: Revocation check
            token_id = claims.get('jti', token_hash)
            if not self._check_revocation(token_id):
                self._cache_result(token_hash, False)
                return {'valid': False, 'error': 'token_revoked'}

            # All checks passed
            self._cache_result(token_hash, True)
            return {'valid': True, 'claims': claims}

        except (ValueError, KeyError, TypeError) as e:
            self._cache_result(token_hash, False)
            return {'valid': False, 'error': str(e)}

    def revoke_token(self, token_id: str):
        """Add token to revocation set."""
        with self._revocation_lock:
            self._revocation_set.add(token_id)


def create_token(claims: Dict[str, Any], key: bytes) -> str:
    """Helper to create a signed token."""
    if not key or len(key) < TokenConfig.MIN_SECRET_LENGTH:
        raise RuntimeError(
            'Signing key must be at least '
            f'{TokenConfig.MIN_SECRET_LENGTH} bytes long'
        )
    header = base64.urlsafe_b64encode(
        json.dumps({'alg': 'HS256', 'typ': 'JWT'}).encode()
    ).decode().rstrip('=')

    payload = base64.urlsafe_b64encode(
        json.dumps(claims).encode()
    ).decode().rstrip('=')

    signature = SignatureEngine.compute_signature(
        f"{header}.{payload}", key
    )

    return f"{header}.{payload}.{signature}"
